+ */
+
+package com.huawei.oss.wireless.experienceassuranceservice.venuealloc.impl.scheduler;
+
+import static org.mockito.Matchers.any;
+import static org.mockito.Matchers.anyLong;
+
+import com.huawei.cloudsop.mockito.adapter.PowerMockRunnerJava21;
+import com.huawei.oss.rpc.raft.server.RaftServer;
+import com.huawei.oss.wireless.experienceassuranceservice.venuealloc.impl.service.SceneTaskLockServiceImpl;
+
+import org.junit.Test;
+import org.junit.runner.RunWith;
+import org.mockito.InjectMocks;
+import org.mockito.Mock;
+import org.mockito.Mockito;
+import org.powermock.api.mockito.PowerMockito;
+import org.powermock.core.classloader.annotations.PowerMockIgnore;
+import org.powermock.core.classloader.annotations.PrepareForTest;
+import org.powermock.reflect.Whitebox;
+
+import java.util.concurrent.ScheduledThreadPoolExecutor;
+
+@RunWith(PowerMockRunnerJava21.class)
+@PowerMockIgnore({"javax.management.*", "jdk.internal.reflect.*"})
+@PrepareForTest({
+    SceneTaskLockRecoveryScheduler.class, ScheduledThreadPoolExecutor.class
+})
+public class SceneTaskLockRecoverySchedulerTest {
+    @InjectMocks private SceneTaskLockRecoveryScheduler sceneTaskLockRecoveryScheduler;
+
+    @Mock private ScheduledThreadPoolExecutor taskExecutor;
+
+    @Mock private RaftServer raftServer;
+
+    @Mock private SceneTaskLockServiceImpl sceneTaskLockServiceImpl;
+
+    @Test
+    public void testInitWhenTaskPostConstruct() throws Exception {
+        PowerMockito.whenNew(ScheduledThreadPoolExecutor.class).withAnyArguments().thenReturn(taskExecutor);
+        sceneTaskLockRecoveryScheduler.init();
+        Mockito.verify(taskExecutor, Mockito.times(1)).scheduleWithFixedDelay(any(), anyLong(), anyLong(), any());
+    }
+
+    @Test
+    public void testRunTaskWhenLeaderThenSuccess() throws Exception {
+        Mockito.when(raftServer.isLeader()).thenReturn(true);
+
+        Whitebox.invokeMethod(sceneTaskLockRecoveryScheduler, "runTask");
+        Mockito.verify(sceneTaskLockServiceImpl).runTask();
+    }
+
+    @Test
+    public void testRunTaskWhenNotLeaderThenSuccess() throws Exception {
+        Mockito.when(raftServer.isLeader()).thenReturn(false);
+
+        Whitebox.invokeMethod(sceneTaskLockRecoveryScheduler, "runTask");
+        Mockito.verify(sceneTaskLockServiceImpl, Mockito.never()).runTask();
+    }
+}
