        } catch (Exception e) {
            LOGGER.info("addScene error.", e);
            writeCreateOrEditOperationLog(scene.getSceneName(), Constants.OPERATION_LEVEL_FAILED, true);
            throw e;
        } finally {
            scenesMgrDBMapper.tryUnlockSceneTask(SCENE_CREATE_LOCK, timeStamp);
