```xml
    <update id="tryLockSceneTask">
        UPDATE T_ALLOC_EVA_CONFIG
        SET VALUE = #{timeStamp}
        WHERE NAME = #{lockName}
          AND VALUE IS NULL
    </update>
    <update id="tryUnlockSceneTask">
        UPDATE T_ALLOC_EVA_CONFIG
        SET VALUE = NULL
        WHERE NAME = #{lockName}
          AND VALUE = #{timeStamp}
    </update>
    <update id="clearExpiredLocks">
        UPDATE T_ALLOC_EVA_CONFIG
        SET VALUE = NULL
        WHERE NAME = #{lockName}
          AND VALUE IS NOT NULL
          AND VALUE &lt; #{threshold}
    </update>
